import itertools

def find_combinations(items, r):
    """Return r-length combinations and permutations of elements."""
    combs = list(itertools.combinations(items, r))
    perms = list(itertools.permutations(items, r))
    return {'combinations': combs, 'permutations': perms}

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_end = True

    def search(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

