def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def accumulator():
    """Generator that receives values via send() and accumulates."""
    total = 0
    while True:
        value = yield total
        if value is None:
