from functools import wraps

def enforce_types(**expected_types):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for name, val in kwargs.items():
                if name in expected_types and not isinstance(val, expected_types[name]):
                    raise TypeError(f"Arg {name} must be {expected_types[name]}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left  = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(l, r):
    result = []
    i = j = 0
    while i < len(l) and j < len(r):
        if l[i] <= r[j]:
            result.append(l[i]); i += 1
        else:
            result.append(r[j]); j += 1
    return result + l[i:] + r[j:]

