def dfs(graph, node, visited=None):
    if visited is None: visited = set()
    visited.add(node)
    path = [node]
    for neighbor in graph.get(node, []):
        if neighbor not in visited:
            path.extend(dfs(graph, neighbor, visited))
    return path

