class Timer:
    import time
    def __enter__(self):
        self.start = self.time.perf_counter()
        return self
    def __exit__(self, exc_type, exc_val, exc_tb):
        self.elapsed = self.time.perf_counter() - self.start
        print(f"Elapsed time: {self.elapsed:.4f}s")
        return False

class ManagedFile:
    """Custom context manager for file handling."""
    def __init__(self, name, mode):
        self.name = name
        self.mode = mode

    def __enter__(self):
        self.file = open(self.name, self.mode)
        return self.file

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.file.close()
        return False

