    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def dfs(graph, start, visited=None):
    if visited is None:
        visited = set()
    visited.add(start)
    for neighbor in graph[start]:
        if neighbor not in visited:
            dfs(graph, neighbor, visited)
    return visited

