from functools import wraps

def repeat(n):
    """Decorator factory: repeat function n times."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(n):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

def count_up_to(max_val):
    """Yield integers sequentially up to a maximum value."""
    count = 1
    while count <= max_val:
        yield count
        count += 1

class Countdown:
    def __init__(self, start):
        self.start = start

    def __iter__(self):
        self.current = self.start
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        self.current -= 1
        return self.current + 1

