class Temperature:
    """Temperature class with Celsius/Fahrenheit via @property."""
    def __init__(self, celsius=0):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError('Temperature below absolute zero')
        self._celsius = value

    @property
    def fahrenheit(self):
        return self._celsius * 9/5 + 32

from functools import wraps

def enforce_types(**expected_types):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for name, val in kwargs.items():
                if name in expected_types and not isinstance(val, expected_types[name]):
                    raise TypeError(f"Arg {name} must be {expected_types[name]}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

