def fibonacci(n):
    """Compute nth Fibonacci number using memoization."""
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

def fib_dp(n):
    """Fibonacci via bottom-up dynamic programming."""
    if n < 2:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i-1] + dp[i-2]
    return dp[n]

