class Timer:
    import time
    def __enter__(self):
        self.start = self.time.perf_counter()
        return self
    def __exit__(self, exc_type, exc_val, exc_tb):
        self.elapsed = self.time.perf_counter() - self.start
        print(f"Elapsed time: {self.elapsed:.4f}s")
        return False

