def fib_dp(n):
    """Fibonacci via bottom-up dynamic programming."""
    if n < 2:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i-1] + dp[i-2]
    return dp[n]

def has_cycle(graph):
    visited = {}  # 0: visiting, 1: visited
    def dfs(node):
        visited[node] = 0
        for nxt in graph.get(node, []):
            if visited.get(nxt) == 0: return True
            if nxt not in visited and dfs(nxt): return True
        visited[node] = 1
        return False
    return any(dfs(n) for n in graph if n not in visited)

