class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_end = True

    def search(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

def has_cycle(graph):
    visited = {}  # 0: visiting, 1: visited
    def dfs(node):
        visited[node] = 0
        for nxt in graph.get(node, []):
            if visited.get(nxt) == 0: return True
            if nxt not in visited and dfs(nxt): return True
        visited[node] = 1
        return False
    return any(dfs(n) for n in graph if n not in visited)

