def read_lines(filename):
    with open(filename) as f:
        yield from f

def strip_lines(lines):
    for line in lines:
        yield line.strip()

def filter_empty(lines):
    for line in lines:
        if line:
            yield line

# Compose pipeline
def pipeline(filename):
    return filter_empty(strip_lines(read_lines(filename)))

